#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        int N = 3*n;
        vector<long long> a(N);
        for(auto &x: a) cin>>x;
        sort(a.rbegin(), a.rend());
        vector<long long> pref(N+1, 0);
        for(int i=0; i<N; i++) pref[i+1] = pref[i] + a[i];
        long long total = pref[N];
        auto smallSum = [&](int k) -> long long {
            return pref[N] - pref[N-k];
        };
        auto bonus = [&](int q, int cntA) -> long long {
            return pref[2*q-cntA] + 2LL*pref[cntA] - 3LL *smallSum(q+cntA);
        };
        auto delta = [&](int q, int cntA) -> long long {
            return 2LL *a[cntA] - a[2*q - cntA - 1] - 3LL * a[N - q - cntA - 1];
        };
        long long bestBonus = 0;
        for(int q = 1; q<=n; ++q){
            int bestA = 0;
            int lo = 0;
            int hi = q-1;
            while(lo <= hi){
                int mid = lo + (hi - lo) / 2;
                if(delta(q, mid) >=0){
                    bestA = mid+1;
                    lo = mid + 1;
                } else hi = mid - 1;
            }
            long long yxz = bonus(q, bestA);
            bestBonus = max(bestBonus, yxz);
        }
        cout<<3LL*total+bestBonus <<endl;
    }
    return 0;
}
